// Brute force: try every pair — O(n²)
int[] twoSum(int[] nums, int target) {
    for (int i = 0; i < nums.length; i++) {
        for (int j = i + 1; j < nums.length; j++) {
            if (nums[i] + nums[j] == target) return new int[]{i, j};
        }
    }
    return new int[0];
}

// Brute force: try every pair — O(n²)
vector<int> twoSum(vector<int>& nums, int target) {
    for (int i = 0; i < (int)nums.size(); i++) {
        for (int j = i + 1; j < (int)nums.size(); j++) {
            if (nums[i] + nums[j] == target) return {i, j};
        }
    }
    return {};
}

// With a hash map: one pass — O(n)
function twoSum(nums, target) {
  const seen = new Map();                         // value -> its index
  for (let i = 0; i < nums.length; i++) {
    const need = target - nums[i];
    if (seen.has(need)) return [seen.get(need), i];   // the partner came earlier
    seen.set(nums[i], i);
  }
  return [];
}

# With a hash map: one pass — O(n)
def two_sum(nums, target):
    seen = {}                                    # value -> its index
    for i, x in enumerate(nums):
        need = target - x
        if need in seen:
            return [seen[need], i]               # the partner came earlier
        seen[x] = i
    return []

// With a hash map: one pass — O(n)
int[] twoSum(int[] nums, int target) {
    Map<Integer, Integer> seen = new HashMap<>();         // value -> its index
    for (int i = 0; i < nums.length; i++) {
        int need = target - nums[i];
        if (seen.containsKey(need)) return new int[]{seen.get(need), i};   // the partner came earlier
        seen.put(nums[i], i);
    }
    return new int[0];
}

// With a hash map: one pass — O(n)
vector<int> twoSum(vector<int>& nums, int target) {
    unordered_map<int, int> seen;                  // value -> its index
    for (int i = 0; i < (int)nums.size(); i++) {
        auto it = seen.find(target - nums[i]);
        if (it != seen.end()) return {it->second, i};   // the partner came earlier
        seen[nums[i]] = i;
    }
    return {};
}
